import sys, random
import importlib.util
spec = importlib.util.spec_from_file_location('entry','/app/submission/entry.py')
m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
Store = m.Store
class Ref:
    def __init__(self): self.d = {}
    def conflicts(self, off, data):
        for i,b in enumerate(data):
            o = off+i
            if o in self.d and self.d[o] != b: return True
        return False
    def store(self, off, data, keep):
        for i,b in enumerate(data):
            o = off+i
            if o in self.d and keep: continue
            self.d[o] = b
    def prefix(self):
        out = bytearray(); i=0
        while i in self.d:
            out.append(self.d[i]); i+=1
        return bytes(out)
random.seed(1234)
for trial in range(300):
    rs = Store(); rr = Ref()
    keep = (trial % 2 == 0)
    hist=[]
    for step in range(60):
        n = random.randint(0, 12)
        if random.random() < 0.3:
            off = random.choice([0,1,127,128,129,255,256,random.randint(0,400)])
        else:
            off = random.randint(0, 10**18)
        data = bytes(random.randint(0,255) for _ in range(n))
        hist.append((off,data,keep))
        c1 = rs.conflicts(off, data); c2 = rr.conflicts(off, data)
        if c1!=c2:
            print('trial',trial,'keep',keep,'step',step,'off',off,'n',n)
            print('hist', [(o,len(d)) for o,d,_ in hist])
            # replay with ref to see state
            r2 = Ref()
            for o,d,k in hist:
                if not r2.conflicts(o,d) or not k: r2.store(o,d,k)
            print('ref dict', sorted(r2.d.items()))
            print('store blocks', {k:(bytes(v[0]).hex(),bin(v[1])) for k,v in rs.blocks.items()})
            break
        if not c1 or not keep:
            j = m.Journal(None)
            rs.store(off, data, j, keep)
            rr.store(off, data, keep)
        assert rs.prefix() == rr.prefix(), ('prefix', off, data, rs.prefix(), rr.prefix())
    else:
        continue
    break
EOF
